	'messages:apihelp-markfortranslation-param-translatetitle' => 'en:If <kbd>yes</kbd>, allow translation of the display title. If <kbd>no</kbd>, do not allow translation. If absent, allow translation unless the page previously disallowed translation, or if the page is a template.',
	'messages:apihelp-markfortranslation-param-prioritylanguages' => 'en:A list of priority language codes. If this is absent, any previously set value will be retained.',
	'messages:apihelp-markfortranslation-param-forcepriority' => 'en:This parameter is ignored unless the <var>prioritylanguages</var> parameter is present. If <kbd>true</kbd>, prevent translations to languages other than the priority languages.',
	'messages:apihelp-markfortranslation-param-priorityreason' => 'en:This parameter is ignored unless the <var>prioritylanguages</var> parameter is present. A string giving the reason for priority translation.',
	'messages:apihelp-markfortranslation-param-nofuzzyunits' => 'en:A list of translation unit IDs which should not be fuzzied. This will be merged with the default list, in which any units with only tvar changes will not be fuzzied.',
	'messages:apihelp-markfortranslation-param-fuzzyunits' => 'en:A list of translation unit IDs which should be fuzzied. This is only useful to override the default and allows fuzzying even units with only tvar changes.',
	'messages:apihelp-markfortranslation-param-forcelatestsyntaxversion' => 'en:If <kbd>false</kbd>, do not use latest syntax version for this page. If absent, latest syntax version is used.',
	'messages:apihelp-markfortranslation-param-transclusion' => 'en:If <kbd>yes</kbd> or absent, enable translation aware transclusion for this page. If <kbd>no</kbd>, disable transclusion.',
	'messages:apierror-translate-changeset-modified' => 'en:The changeset has been modified by another user or process. Your changes cannot be saved as it might override their changes. Please refresh the page to see the latest changes.',
	'messages:apierror-translate-fuzzymessage' => 'en:Cannot review fuzzy translations',
	'messages:apierror-translate-invalidfilter' => 'en:$1',
	'messages:apierror-translate-invalidstate' => 'en:The requested state is invalid.',
	'messages:apierror-translate-nomessagefortitle' => 'en:Title does not correspond to a translatable message',
	'messages:apierror-translate-sandbox-invalidparam' => 'en:$1',
	'messages:apierror-translate-sandbox-user-add' => 'en:There was an error while adding a new user',
	'messages:apierror-translate-invalid-changeset-name' => 'en:Invalid changeset file name passed - $1',
	'messages:apierror-translate-addition-key-invalid' => 'en:Message key passed for addition was not found in the renamed message list for source language.',
	'messages:apierror-translate-rename-msg-new' => 'en:Only renamed messages can be added as new messages.',
	'messages:apierror-translate-rename-key-invalid' => 'en:Message keys passed for rename were not found in the list of changes for the source language.',
	'messages:apierror-translate-rename-state-invalid' => 'en:One of the message passed for rename should be newly added, and the other one deleted. Current states - addition: $1 and deletion: $2.',
	'messages:apierror-translate-messagegroupsubscription-disabled' => 'en:Message group subscription is not enabled',
	'messages:apierror-translate-messagegroupsubscription-dynamic-group-unsupported' => 'en:Watching dynamic message groups is not supported',
	'messages:apierror-markfortranslation-invalid-prioritylangs' => 'en:Invalid language {{PLURAL:$1|code|codes}} specified for priority languages: $2',
	'messages:apiwarn-translate-language-targetlang-variant-of-source' => 'en:<strong>You are translating into <bdi>$1</bdi>.</strong> It is a variant of <bdi>$2</bdi>, which is already the source language of these messages. Make sure the selected language is correct, and consider the differences across the language variants to provide a good translation.',
	'messages:apierror-translate-operation-error' => 'en:There was an error while processing the request. Error: $1',
	'messages:apihelp-translationentitysearch-param-entitytype' => 'en:Entity type being queried',
	'messages:apihelp-translationentitysearch-param-grouptypes' => 'en:Group type(s) to filter by',
	'messages:tsb-other-actions' => 'en:You need to [[Special:TranslationStash|submit some test translations]] and have them approved before editing.',
	'messages:tux-sst-search-info' => 'en:Use operators <code>language:</code> or <code>group:</code> to further qualify the search criteria',
	'messages:tux-sst-error-unsupported-language' => 'en:Search in language <code>$1</code> is not supported.',
	'messages:contactpage-mustbeloggedin-for-temp-user' => 'en:Please create an account to submit a contact form.',
	'messages:contactpage-musthaveemail-error-title' => 'en:Missing confirmed email address',
	'messages:contactpage-musthaveemail-error' => 'en:Please set a confirmed email address in your [[Special:Preferences|preferences]] to submit a contact form.',
